solutions.naive:
class Solution:
    def carPooling(self, trips: list[list[int]], capacity: int) -> bool:
        last = max(end for _, _, end in trips)
        for pos in range(last):
            riders = 0
            for passengers, start, end in trips:
                if start <= pos < end:
                    riders += passengers
            if riders > capacity:
                return False
        return True

solutions.better:
class Solution:
    def carPooling(self, trips: list[list[int]], capacity: int) -> bool:
        last = max(end for _, _, end in trips)
        diff = [0] * (last + 1)
        for passengers, start, end in trips:
            diff[start] += passengers
            diff[end] -= passengers
        riders = 0
        for change in diff:
            riders += change
            if riders > capacity:
                return False
        return True

solutions.optimal:
class Solution:
    def carPooling(self, trips: list[list[int]], capacity: int) -> bool:
        events = []
        for passengers, start, end in trips:
            events.append((start, passengers))
            events.append((end, -passengers))
        events.sort()
        riders = 0
        for _, change in events:
            riders += change
            if riders > capacity:
                return False
        return True

